import json

def extract_failed_reason(message):
  json_str = message.split("400 - ", 1)[1]
  clean = json_str.strip('"').encode("utf-8").decode("unicode_escape")
  parsed = json.loads(clean)
  return parsed["error"]["message"]["value"]

for item in _input.all():
  if item.json.error.message.startswith('400 - '):
    item.json.failed_reason = extract_failed_reason(item.json.error.message)
  else:
    item.json.failed_reason = item.json.error.message

return _input.all()

